"""`ah env template --master [--check]`: the master and the environment templates, written from
the declarations.

The master opens with a generated top block. Each key follows its block header, with its
`summary` as one comment line above it and its `default` as the value. A template
`.env.<env>.example` holds each key that `<env>` carries (see `Key.applies_to`), with the value
of `[environments.<env>]` or an empty one, and no comment line: it is a plain file.
"""

from __future__ import annotations

from pathlib import Path

from agent_harness import HarnessError
from agent_harness.env import declarations, envfile
from agent_harness.env.args import Args, expect
from agent_harness.env.context import Context

TOP_BLOCK = [
    "# Generated by `ah env template --master` from the env declarations. Do not edit it.",
    "#",
    "# Every other env file follows its blocks and key order.",
]


def master_text(decl: declarations.Declarations) -> str:
    lines = [*TOP_BLOCK]
    block = None
    for key in decl.keys:
        if key.block != block:
            block = key.block
            lines += ["", f"# {block}"]
        if key.summary:
            lines.append(f"# {key.summary}")
        lines += envfile.lines_for(key.name, key.default)
    return "\n".join(lines) + "\n"


def environment_text(decl: declarations.Declarations, environment: str) -> str:
    values = decl.environments.get(environment, {})
    lines: list[str] = []
    block = None
    for key in decl.keys:
        if not key.applies_to(environment):
            continue
        if key.block != block:
            block = key.block
            lines += [*([""] if lines else []), f"# {block}"]
        lines += envfile.lines_for(key.name, values.get(key.name, ""))
    return "\n".join(lines) + "\n" if lines else ""


def environments_of(decl: declarations.Declarations) -> list[str]:
    named = {env for key in decl.keys for env in key.environments or []}
    return sorted(named | set(decl.environments))


def targets(ctx: Context) -> dict[Path, str]:
    """Each template path and the text the declarations give it."""
    if not ctx.settings.get("declarations"):
        raise HarnessError(
            "template --master writes from the declarations, and none are configured"
        )
    decl = ctx.declarations()
    folder = ctx.master.parent
    out = {ctx.master: master_text(decl)}
    for environment in environments_of(decl):
        text = environment_text(decl, environment)
        if text:
            out[folder / f".env.{environment}.example"] = text
    return out


def cmd_template_master(ctx: Context, args: Args) -> int:
    expect(args, 0, 0, "no file: template --master writes every template")
    texts = targets(ctx)
    if args.flags.get("--check"):
        return check(ctx, texts)
    for path, text in texts.items():
        ctx.destination(path)
        keys = envfile.parse(text, str(path)).key_names()
        envfile.write_text(path, text, mode=0o644)
        ctx.out(f"wrote {ctx.show(path)}: {len(keys)} keys")
    return 0


def check(ctx: Context, texts: dict[Path, str]) -> int:
    differ = 0
    for path, text in texts.items():
        if not path.is_file():
            ctx.out(f"missing: {ctx.show(path)}")
        elif path.read_text(encoding="utf-8") != text:
            ctx.out(f"stale: {ctx.show(path)}")
        else:
            continue
        differ += 1
    if differ:
        ctx.out(f"{differ} templates differ from the declarations. Run ah env template --master.")
        return 1
    ctx.out(f"{len(texts)} templates match the declarations")
    return 0
